def rebuild_coty_bonuses(apps, schema_editor, *, include_bp=False):
    """Apply the rule to stored COTY totals without changing earlier seasons."""
    coty_model = apps.get_model("core", "COTY")
    quals_model = apps.get_model("core", "QUAL")
    points_model = apps.get_model("core", "QualPoints")
    database = schema_editor.connection.alias
    rows = coty_model.objects.using(database)
    seasons = list(rows.order_by().values_list("season", flat=True).distinct())
    for season in seasons:
        try:
            if int(str(season).split("-", maxsplit=1)[0]) < 2026:
                continue
        except (TypeError, ValueError):
            continue
        updated = []
        for row in rows.filter(season=season).select_related("school"):
            if not row.school.included_in_oty:
                rows.filter(pk=row.pk).delete()
                continue
            points = sum(
                min(60, value) for value in points_model.objects.using(database).filter(
                    season=season, debater__school_id=row.school_id
                ).values_list("points", flat=True)
            )
            quals = quals_model.objects.using(database).filter(
                season=season, debater__school_id=row.school_id
            )
            if not include_bp:
                quals = quals.exclude(qual_type__in=(1, 2, 3, 5, 6, 16))
            points += quals.values("debater_id").distinct().count() * 6
            if points > 0:
                updated.append((row.pk, points))
            else:
                rows.filter(pk=row.pk).delete()
        updated.sort(key=lambda item: (-item[1], item[0]))
        for pk, points in updated:
            place = next(i + 1 for i, item in enumerate(updated) if item[1] == points)
            tied = sum(item[1] == points for item in updated) > 1
            rows.filter(pk=pk).update(points=points, place=place, tied=tied)
        cache.delete(make_template_fragment_key("coty", [season]))
        cache.delete(f"api:standings_replay:{season}")


def restore_coty_bonuses(apps, schema_editor):
    rebuild_coty_bonuses(apps, schema_editor, include_bp=True)


